'use client';

import { createField } from '@dawitlabs/pixelfield';
import { useEffect, useRef } from 'react';

export interface SilkProps {
  className?: string;
  tint?: string;
  seed?: number;
  interactive?: boolean;
}

export function Silk({ className, tint, seed = 0, interactive = true }: SilkProps) {
  const ref = useRef<HTMLCanvasElement>(null);

  useEffect(() => {
    const canvas = ref.current;
    if (!canvas) return;
    const field = createField(canvas, {
      generator: 'waves',
      falloff: 'fill',
      scale: 0.85,
      aspect: 1,
      warp: 0.45,
      contrast: 0.85,
      mode: 'fbm',
      speed: 0.8,
      intensity: 1,
      flow: { x: 0, y: 0 },
      seed,
      tint,
      interactive,
    });
    return () => field.destroy();
  }, [tint, seed, interactive]);

  return <canvas ref={ref} className={className} aria-hidden="true" />;
}

import { createField } from '@dawitlabs/pixelfield';

export function mountSilk(canvas, { tint, seed = 0, interactive = true } = {}) {
  return createField(canvas, {
      generator: 'waves',
      falloff: 'fill',
      scale: 0.85,
      aspect: 1,
      warp: 0.45,
      contrast: 0.85,
      mode: 'fbm',
      speed: 0.8,
      intensity: 1,
      flow: { x: 0, y: 0 },
    seed,
    tint,
    interactive,
  });
}
